CREATE VIEW health_demo.foods AS SELECT id,v.1 AS name,v.2 AS description,v.3 AS calories,v.4 AS protein,v.5 AS carbs,v.6 AS fat,v.7 AS serving_grams,v.8 AS vegan,v.9 AS embedding,v.10 AS embedding_model,v.11 AS embedding_text,v.12 AS deleted,version FROM (SELECT id,argMax(tuple(name,description,calories,protein,carbs,fat,serving_grams,vegan,embedding,embedding_model,embedding_text,_peerdb_is_deleted),_peerdb_version) AS v,max(_peerdb_version) AS version FROM default.foods_cdc GROUP BY id) WHERE length(embedding)=384 AND arrayAll(x -> isFinite(x),embedding) AND embedding_text=concat(name,'. ',description) AND embedding_model='sentence-transformers/all-MiniLM-L6-v2';
CREATE VIEW health_demo.meals AS SELECT id,v.1 AS user_id,v.2 AS label,v.3 AS logged_at,v.4 AS items,v.5 AS calories,v.6 AS protein,v.7 AS carbs,v.8 AS fat,v.9 AS deleted,version FROM (SELECT id,argMax(tuple(user_id,label,logged_at,items,calories,protein,carbs,fat,_peerdb_is_deleted),_peerdb_version) AS v,max(_peerdb_version) AS version FROM default.meals_cdc GROUP BY id);
